const {chromium}=require('C:/Users/Administrator/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright'),assert=require('node:assert/strict'),assets=require('./character-assets.js'),sprites=require('./fighting-sprites.js');
const original=JSON.stringify(assets),frames=sprites.create(assets);assert.equal(JSON.stringify(assets),original);for(const id of assets.ids){assert.equal(frames[id].punch.length,5);assert.equal(frames[id].kick.length,5);assert.notDeepEqual(frames[id].punch[0].rows,frames[id].punch[2].rows);assert.notDeepEqual(frames[id].kick[0].rows,frames[id].kick[2].rows);}
(async()=>{const b=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true}),p=await b.newPage({viewport:{width:1400,height:1000}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto('http://localhost:4173/fighting.html');await p.selectOption('#mode','local');await p.click('#start');await p.waitForFunction(()=>PixelFighting.snapshot.phase==='fight');await p.keyboard.press('KeyJ');await p.waitForTimeout(110);await p.locator('#arena').screenshot({path:__dirname+'/fighting-natural-punch.png'});await p.waitForTimeout(400);await p.keyboard.press('KeyK');await p.waitForTimeout(220);await p.locator('#arena').screenshot({path:__dirname+'/fighting-natural-kick.png'});assert(await p.evaluate(()=>{let calls=0;const c=new Proxy({},{get:()=>()=>calls++});for(const kind of ['light','heavy'])PixelFightingVFX.attack(c,{id:'goku',action:{kind,start:.13,duration:.32,t:.1},x:200,y:440,facing:1},1,96,'#fff');return calls===0&&!PixelFightingVFX.dock;}));
await p.evaluate(()=>{const c=document.createElement('canvas');c.id='pose-review';c.width=960;c.height=600;const cx=c.getContext('2d');cx.fillStyle='#172b36';cx.fillRect(0,0,960,600);for(const [i,id] of PixelQuestCharacters.ids.entries()){const col=i%3,row=Math.floor(i/3),left=col*320;cx.font='16px monospace';cx.fillStyle='#ffdb86';cx.fillText(PixelQuestCharacters.names[id],left+15,row*300+30);for(const [j,kind] of ['idle','light','heavy'].entries()){const fighter={id,x:left+55+j*100,y:row*300+185,facing:1,vx:0,ground:true,roll:0,flash:0,action:kind==='idle'?null:{kind,t:kind==='light'?.12:.24,start:kind==='light'?.13:.25,duration:kind==='light'?.32:.57}};PixelFightingSprites.draw(cx,fighter,0,PixelQuestCharacters);cx.fillStyle='#afc6ce';cx.fillText(kind,fighter.x-24,row*300+220);}}document.body.append(c);});await p.locator('#pose-review').screenshot({path:__dirname+'/fighting-six-poses.png'});assert.deepEqual(errors,[]);console.log('PASS six independent punch/kick pose sets, shared assets untouched, plain melee rendering and no in-arena dock; no browser errors');await b.close();})().catch(e=>{console.error(e);process.exit(1);});
